/// The method and route of every request, for the server's router test.
pub fn every() -> Vec<(&'static str, &'static str)> {
    macro_rules! all {
        ($($t:ty),* $(,)?) => { vec![$((<$t>::METHOD, <$t>::ROUTE)),*] };
    }
    all![
        EngineStatus,
        Doctor,
        StackStatus,
        StackStart,
        StackStop,
        Console,
        ContainerLogs,
        ContainerStop,
        ContainerStart,
        Workspaces,
        WorkspaceAdd,
        Jobs,
        Job,
        JobSubmit,
        JobApprove,
        JobComment,
        JobStop,
        Dials,
        DialsSet,
        HeldAllow,
        HeldRefuse,
        Constraints,
        ConstraintAdd,
        ConstraintMove,
        Capabilities,
        CapabilityMove,
        FactoryCapabilities,
        Charters,
        Audit,
        AuditExport,
        Evals,
        EvalCreate,
        Eval,
        EvalApply,
        Settings,
        SettingsSet,
        SettingsPreset,
        SettingsHistory,
        SettingsRestore,
        Models,
        Accounts,
        Issues,
        JobFromIssue,
        Me,
        People,
        PersonAdd,
        PersonRole,
        TokenIssue,
        Tokens,
        TokenRevoke,
        Providers,
        ProviderKeySet,
        ProviderKeyRemove,
        CodexSignIn,
        CodexSignInPoll,
        CodexSignOut,
        Hosts,
        HostsSet,
        Workflows,
        WorkflowCopy,
        WorkflowSave,
        WorkflowDelete,
    ]
}

