560	//! Calls to a Bastion server (PLAN.md D28): each command goes over HTTP by
561	//! the route table in `bastion-protocol`, with the server's bearer token.
562	
563	use std::time::Duration;
564	
565	use bastion_protocol::Server;
566	use bastion_protocol::api::Request;
567	use bastion_protocol::routes::{self, Body};
568	use serde_json::{Map, Value};
569	
570	/// How long a server has to accept a connection.
571	const CONNECT: Duration = Duration::from_secs(5);
572	/// How long a call may take, start of a stack included.
573	const CALL: Duration = Duration::from_secs(120);
574	/// How long the event stream may stay silent. The server sends a keep-alive
575	/// every 15 s, so silence past this means a half-open connection.
576	const SILENCE: Duration = Duration::from_secs(45);
577	
578	/// One HTTP client for every call, so connections are kept.
579	pub fn http() -> reqwest::Client {
580	    let built = reqwest::Client::builder()
581	        .connect_timeout(CONNECT)
582	        .timeout(CALL)
583	        .build();
584	    built.expect("the TLS backend loads")
585	}
586	
587	/// The client for a server's event stream: no limit on the whole stream,
588	/// only on each silence.
589	pub fn stream_http() -> reqwest::Client {
590	    let built = reqwest::Client::builder()
591	        .connect_timeout(CONNECT)
592	        .read_timeout(SILENCE)
593	        .build();
594	    built.expect("the TLS backend loads")
595	}
596	
597	/// One command for a server and its arguments.
598	pub struct Ask {
599	    pub cmd: &'static str,
600	    pub args: Value,
601	}
602	
603	impl Ask {
604	    /// A command with no arguments.
605	    pub fn bare(cmd: &'static str) -> Self {
606	        Ask {
607	            cmd,
608	            args: Value::Null,
609	        }
610	    }
611	}
612	
613	/// Send `ask` to `server`, and return its answer, or the server's refusal
614	/// as text.
615	pub async fn call(http: reqwest::Client, server: Server, ask: Ask) -> Result<Value, String> {
616	    let Ask { cmd, args } = ask;
617	    let (method, path, body) =
618	        routes::route(cmd).ok_or_else(|| format!("{cmd} is not a server command"))?;
619	    let mut args = match args {
620	        Value::Object(map) => map,
621	        _ => Map::new(),
622	    };
623	    let path = fill(path, &mut args);
624	    let body = match body {
625	        Body::Empty => None,
626	        Body::Field(name) => args.remove(name),
627	        Body::Rest => Some(Value::Object(args)),
628	    };
629	    let url = format!("{}{path}", server.url.trim_end_matches('/'));
630	    let method = reqwest::Method::from_bytes(method.as_bytes()).map_err(|e| e.to_string())?;
631	    let mut request = http.request(method, url).bearer_auth(&server.token);
632	    if let Some(body) = body {
633	        request = request.json(&body);
634	    }
635	    let unreachable = |_| {
636	        format!(
637	            "The Bastion server {} at {} cannot be reached.",
638	            server.name, server.url
639	        )
640	    };
641	    let response = request.send().await.map_err(unreachable)?;
642	    let ok = response.status().is_success();
643	    let text = response.text().await.unwrap_or_default();
644	    answer(ok, &text)
645	}
646	
647	/// Send `request` to `server`, and read its answer, or the server's
648	/// refusal as text.
649	pub async fn send<R: Request>(
650	    http: &reqwest::Client,
651	    server: &Server,
652	    request: &R,
653	) -> Result<R::Answer, String> {
654	    let url = format!("{}{}", server.url.trim_end_matches('/'), request.path());
655	    let method = reqwest::Method::from_bytes(R::METHOD.as_bytes()).map_err(|e| e.to_string())?;
656	    let mut sent = http.request(method, url).bearer_auth(&server.token);
657	    if R::BODY {
658	        sent = sent.json(request);
659	    }
660	    let unreachable = |_| {
661	        format!(
662	            "The Bastion server {} at {} cannot be reached.",
663	            server.name, server.url
664	        )
665	    };
666	    let response = sent.send().await.map_err(unreachable)?;
667	    let ok = response.status().is_success();
668	    let text = response.text().await.unwrap_or_default();
669	    serde_json::from_value(answer(ok, &text)?).map_err(|e| e.to_string())
670	}
671	
672	/// A success's value, or a refusal's text: `{ "error": text }`, or the
673	/// typed error as it is.
674	fn answer(ok: bool, text: &str) -> Result<Value, String> {
675	    let value: Value = serde_json::from_str(text).unwrap_or(Value::Null);
676	    if ok {
677	        return Ok(value);
678	    }
679	    match value.get("error").cloned().unwrap_or(value) {
680	        Value::String(why) => Err(why),
681	        other => Err(other.to_string()),
682	    }
683	}
684	
685	/// Put each `{name}` argument into the path, and take it out of the args.
686	fn fill(template: &str, args: &mut Map<String, Value>) -> String {
687	    let mut path = template.to_string();
688	    while let Some(start) = path.find('{') {
689	        let end = start + path[start..].find('}').unwrap_or(0);
690	        let name = path[start + 1..end].to_string();
691	        let value = match args.remove(&name) {
692	            Some(Value::String(s)) => s,
693	            Some(other) => other.to_string(),
694	            None => String::new(),
695	        };
696	        path.replace_range(start..=end, &encode(&value));
697	    }
698	    path
699	}
700	
701	/// A path segment, percent-encoded.
702	fn encode(segment: &str) -> String {
703	    let kept = |b: u8| b.is_ascii_alphanumeric() || b"-._~".contains(&b);
704	    segment
705	        .bytes()
706	        .map(|b| {
707	            if kept(b) {
708	                (b as char).to_string()
709	            } else {
710	                format!("%{b:02X}")
711	            }
712	        })
713	        .collect()
714	}
