785	impl Ctx {
786	    fn server(&self, name: &str) -> Result<Server, String> {
787	        let found = self.servers.iter().find(|s| s.name == name);
788	        found
789	            .cloned()
790	            .ok_or_else(|| format!("no Bastion server named {name}"))
791	    }
