793	    /// Send `ask` to the server named `on`, and read its answer as `T`.
794	    pub async fn get<T: DeserializeOwned>(self, on: String, ask: Ask) -> Result<T, String> {
795	        let server = self.server(&on)?;
796	        let value = client::call(self.http, server, ask).await?;
797	        serde_json::from_value(value).map_err(|e| e.to_string())
798	    }
799	
800	    /// A task that sends `ask` to `on` and hands its answer to `then`.
801	    pub fn task<T, M>(&self, on: &str, ask: Ask, then: fn(Result<T, String>) -> M) -> Task<M>
802	    where
803	        T: DeserializeOwned + Send + 'static,
804	        M: Send + 'static,
805	    {
806	        Task::perform(self.clone().get(on.to_string(), ask), then)
807	    }
808	}
