810	/// A status mark and its color, as a run of steps shows them.
811	pub fn mark(state: &str) -> (&'static str, Color) {
812	    match state {
813	        "done" | "landed" => ("✓", theme::OK),
814	        "running" | "provisioning" => ("●", theme::LINK),
815	        "waiting" | "needs_you" => ("!", theme::WARN),
816	        "failed" => ("✕", theme::BAD),
817	        "stopped" => ("■", theme::MUTED),
818	        "queued" => ("◌", theme::MUTED),
819	        _ => ("○", theme::MUTED),
820	    }
821	}
