823	/// "3 min ago", from seconds since the epoch.
824	pub fn ago(at: u64) -> String {
825	    let now = SystemTime::now()
826	        .duration_since(UNIX_EPOCH)
827	        .map_or(0, |d| d.as_secs());
828	    match now.saturating_sub(at) {
829	        s if s < 60 => "just now".into(),
830	        s if s < 3600 => format!("{} min ago", s / 60),
831	        s if s < 86_400 => format!("{} h ago", s / 3600),
832	        s => format!("{} d ago", s / 86_400),
833	    }
834	}
