836	/// A titled section: a rounded panel with its title above a line. An
837	/// accented one has the warning color's edge.
838	pub fn section<'a, M: 'a>(title: String, body: Element<'a, M>, accent: bool) -> Element<'a, M> {
839	    let head =
840	        container(text(title).size(13).color(theme::MUTED).font(theme::BOLD)).padding([8, 12]);
841	    let style = if accent {
842	        theme::accented
843	    } else {
844	        theme::panel
845	    };
846	    container(column![head, theme::rule(), body])
847	        .width(Fill)
848	        .style(style)
849	        .into()
850	}
