873	
874	/// The id of every page's scroll area, so a new page starts at its top.
875	pub const SCROLL: &str = "page";
876	
877	/// A page's body in its scroll area, clear of the scroll bar.
878	pub fn scrolled<'a, M: 'a>(body: impl Into<Element<'a, M>>) -> Element<'a, M> {
879	    let body = container(body).padding(iced::Padding::ZERO.right(16));
880	    iced::widget::scrollable(body)
881	        .id(SCROLL)
882	        .height(Fill)
883	        .into()
884	}
885	
886	/// A label above a field, as the forms show them.
887	pub fn labeled<'a, M: 'a>(label: &'a str, field: impl Into<Element<'a, M>>) -> Element<'a, M> {
888	    column![text(label).size(13).color(theme::MUTED), field.into()]
889	        .spacing(4)
890	        .into()
891	}
892	
893	/// What a push says changed, so a page reads again only what it shows.
894	#[derive(Clone, Copy, Debug, PartialEq)]
895	pub enum Push {
896	    /// Read everything: a page just opened, changes were missed, or a
897	    /// change reached every job (a setting, say).
898	    All,
899	    /// One job changed.
900	    Job,
901	    /// The engine or its console changed.
902	    Engine,
903	}
904	
905	/// The page the window shows, with its state.
906	pub enum Page {
907	    Jobs(jobs::State),
908	    NewRequest(new_request::State),
909	    Job(Box<job::State>),
910	    Govern(govern::State),
911	    Engine(Box<engine::State>),
912	    Evals(Box<evals::List>),
913	    Eval(Box<evals::One>),
914	    Settings(Box<settings::State>),
915	    Workflows(Box<workflows::State>),
916	    /// Nothing yet: the window has not reached its first server.
917	    Pending,
918	}
919	
920	impl Page {
921	    /// The page for `route`, and its first read.
922	    pub fn open(route: &Route, ctx: &Ctx) -> (Page, Task<Message>) {
923	        let page = match route {
924	            Route::Jobs => Page::Jobs(jobs::State::default()),
925	            Route::NewRequest => Page::NewRequest(new_request::State::default()),
926	            Route::Job(id) => Page::Job(Box::new(job::State::new(id.clone()))),
927	            Route::Constraints => Page::Govern(govern::State::new(govern::Which::Constraints)),
928	            Route::Capabilities => Page::Govern(govern::State::new(govern::Which::Capabilities)),
929	            Route::Audit => Page::Govern(govern::State::new(govern::Which::Audit)),
930	            Route::Engine => Page::Engine(Box::default()),
931	            Route::Evals => Page::Evals(Box::default()),
932	            Route::Eval(id) => Page::Eval(Box::new(evals::One::new(id.clone()))),
933	            Route::Settings => Page::Settings(Box::default()),
934	            Route::Workflows => Page::Workflows(Box::default()),
935	        };
936	        let first = page.reload(ctx, Push::All);
937	        (page, first)
938	    }
939	
940	    /// Whether `push` changed what the page shows.
941	    fn wants(&self, push: Push) -> bool {
942	        match self {
943	            Page::Pending => false,
944	            Page::NewRequest(_) | Page::Settings(_) => push == Push::All,
945	            Page::Engine(_) => push != Push::Job,
946	            // ponytail: any job's change reads a job or an eval again; pass the id when that costs.
947	            _ => push != Push::Engine,
948	        }
949	    }
950	
951	    /// Read what the page shows.
952	    fn load(&self, ctx: &Ctx) -> Task<Message> {
953	        match self {
954	            Page::Jobs(s) => jobs::load(s, ctx).map(Message::Jobs),
955	            Page::NewRequest(s) => new_request::load(s, ctx),
956	            Page::Job(s) => job::load(s, ctx),
957	            Page::Govern(s) => govern::load(s, ctx),
958	            Page::Engine(_) => engine::load(ctx),
959	            Page::Evals(_) => evals::load_list(ctx),
960	            Page::Eval(s) => evals::load_one(s, ctx),
961	            Page::Settings(_) => settings::load(ctx),
962	            Page::Workflows(_) => workflows::load(ctx),
963	            Page::Pending => Task::none(),
964	        }
965	    }
966	
967	    /// Read again after a push, when it changed what the page shows.
968	    pub fn reload(&self, ctx: &Ctx, push: Push) -> Task<Message> {
969	        if self.wants(push) {
970	            self.load(ctx)
971	        } else {
972	            Task::none()
973	        }
974	    }
975	
976	    /// Hand a page's message to the page it belongs to; one for a page no
977	    /// longer shown is dropped.
978	    pub fn update(&mut self, message: Message, ctx: &Ctx) -> Task<Message> {
979	        match (self, message) {
980	            (Page::Jobs(s), Message::Jobs(m)) => jobs::update(s, m),
981	            (Page::NewRequest(s), Message::NewRequest(m)) => return new_request::update(s, m, ctx),
982	            (Page::Job(s), Message::Job(m)) => return job::update(s, m, ctx),
983	            (Page::Govern(s), Message::Govern(m)) => return govern::update(s, m, ctx),
984	            (Page::Engine(s), Message::Engine(m)) => return engine::update(s, m, ctx),
985	            (Page::Evals(s), Message::Evals(m)) => return evals::update_list(s, m, ctx),
986	            (Page::Eval(s), Message::Evals(m)) => return evals::update_one(s, m, ctx),
987	            (Page::Settings(s), Message::Settings(m)) => return settings::update(s, m, ctx),
988	            (Page::Workflows(s), Message::Workflows(m)) => return workflows::update(s, m, ctx),
989	            _ => {}
990	        }
991	        Task::none()
992	    }
993	
994	    pub fn view<'a>(&'a self, route: &Route, ctx: &Ctx) -> Element<'a, Message> {
995	        match self {
996	            Page::Jobs(s) => jobs::view(s, ctx),
997	            Page::NewRequest(s) => new_request::view(s, ctx),
998	            Page::Job(s) => job::view(s, ctx),
999	            Page::Govern(s) => govern::view(s),
1000	            Page::Engine(s) => engine::view(s),
1001	            Page::Evals(s) => evals::view_list(s),
1002	            Page::Eval(s) => evals::view_one(s, ctx),
1003	            Page::Settings(s) => settings::view(s, ctx),
1004	            Page::Workflows(s) => workflows::view(s),
1005	            Page::Pending => {
1006	                let title = text(route.title()).size(24).font(theme::BOLD);
1007	                let note = text("Reaching the Bastion server…").color(theme::MUTED);
1008	                column![title, note].spacing(12).into()
1009	            }
1010	        }
1011	    }
1012	}
