];

#[derive(Default)]
pub struct State {
    all: Vec<WorkflowView>,
    chosen: String,
    draft: Option<WorkflowView>,
    picked: Pick,
    drag: Option<Drag>,
    admin: bool,
    /// The picked step's note and results as typed.
    note: text_editor::Content,
