use crate::route::Route;
use crate::theme;

const RUNGS: [&str; 3] = ["told", "checked", "enforced"];

fn short(base: &str) -> &str {
    &base[..7.min(base.len())]
}

/// The form to run an eval: requests, and the one rung A and B set.
pub struct Form {
    open: bool,
    name: String,
    workspaces: Vec<Workspace>,
        One {
            id,
            eval: None,
            error: String::new(),
            note: String::new(),
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Rung {
    A,
