    .on_press(msg(Msg::ToggleForm));
    if !form.open {
        return container(toggle)
            .padding(8)
            .width(Fill)
            .style(theme::panel)
            .into();
    }
    let spaces: Vec<String> = form.workspaces.iter().map(|w| w.name.clone()).collect();

